// Check if boxes are separated
for (int i = 0; i < 3; i++) {
    if (box1.max[i] < box2.min[i] || box1.min[i] > box2.max[i]) {
        return BoxRelation::Separated;
    }
}

// Check if boxes are adjacent
bool adjacent = false;
for (int i = 0; i < 3; i++) {
    if (std::abs(box1.max[i] - box2.min[i]) < 1e-9 || std::abs(box1.min[i] - box2.max[i]) < 1e-9) {
        adjacent = true;
    } else if (box1.max[i] < box2.min[i] || box1.min[i] > box2.max[i]) {
        // Separated in this dimension
        return BoxRelation::Separated;
    }
}

if (adjacent) {
    return BoxRelation::Adjacent;
}

// Otherwise they are overlapped
return BoxRelation::Overlapped;
// END_CODE

